// ============================================================================
// my-PV AC•THOR controller & scheduler
// ============================================================================
// Configuration: these are the only values that normally need adjustment.
const DEVICE_IP = '192.168.1.100'
const LANGUAGE_CODE = 'en' // Supported: en, de, es, fr, it, nl

const BACKOFF_MS = 200
const SET_INTERVAL_MS = 4000
const SET_MAX_INTERVAL_MS = 5000
const DATA_INTERVAL_MS = 2000
const DATA_MAX_INTERVAL_MS = 2500
const SETUP_INTERVAL_MS = 45000
const STARTUP_SETUP_RETRY_INTERVAL_MS = 5000
const COMMUNICATION_TIMEOUT_MS = 30000
const HTTP_REQUEST_TIMEOUT_MS = 10000
const MAX_RETRIES = 3

const STATE_KEY = 'mypv_state'
const now = Date.now()

// AC•THOR operation-state labels from the my-PV web application.
// State 7 is a local fallback used when the device reports no known state.
const infoStateLabels = {
    en: [
        'Standby',
        'Heating',
        'Boost heating',
        'Heating finished',
        'No communication',
        'Error',
        'Device blocked',
        'Unknown'
    ],
    de: [
        'Standby',
        'Heizen',
        'Heizen Sicherstellung',
        'Heizen beendet',
        'Keine Verbindung',
        'Fehler',
        'Sperrzeit aktiv',
        'Unbekannt'
    ],
    es: [
        'Standby',
        'Calentamiento',
        'Boost calentamiento',
        'El calentamiento se acabó',
        'No hay conexión',
        'Error',
        'Tiempo de parada activo',
        'Desconocido'
    ],
    fr: [
        'Standby',
        'Chauffage',
        'Sécurisation chauffage',
        'Chauffage terminé',
        'Pas de connexion',
        'Erreur',
        'Blocage activé',
        'Inconnu'
    ],
    it: [
        'Standby',
        'Riscaldamento',
        'Assicurazione del riscaldamento',
        'Riscaldamento terminato',
        'Nessuna connessione',
        'Errore',
        'Tempo di blocco attivo',
        'Sconosciuto'
    ],
    nl: [
        'Stand-by',
        'Verwarmen',
        'Verwarmen (zekerstelling)',
        'Verwarmen beëindigd',
        'Geen verbinding',
        'Fout',
        'Blokkeertijd actief',
        'Onbekend'
    ]
}

const labels = infoStateLabels[LANGUAGE_CODE] || infoStateLabels.en

// Dashboard text translated with the same LANGUAGE_CODE setting.
const uiTextLabels = {
    en: {
        mode: 'Mode',
        waterTemperature: 'Water temperature',
        power: 'Power',
        reported: 'Reported',
        status: 'Status',
        controller: 'Controller'
    },
    de: {
        mode: 'Modus',
        waterTemperature: 'Wassertemperatur',
        power: 'Leistung',
        reported: 'Gemeldet',
        status: 'Status',
        controller: 'Regler'
    },
    es: {
        mode: 'Modo',
        waterTemperature: 'Temperatura del agua',
        power: 'Potencia',
        reported: 'Informada',
        status: 'Estado',
        controller: 'Controlador'
    },
    fr: {
        mode: 'Mode',
        waterTemperature: "Température de l'eau",
        power: 'Puissance',
        reported: 'Rapportée',
        status: 'État',
        controller: 'Contrôleur'
    },
    it: {
        mode: 'Modalità',
        waterTemperature: 'Temperatura acqua',
        power: 'Potenza',
        reported: 'Riportata',
        status: 'Stato',
        controller: 'Controllore'
    },
    nl: {
        mode: 'Modus',
        waterTemperature: 'Watertemperatuur',
        power: 'Vermogen',
        reported: 'Gemeld',
        status: 'Status',
        controller: 'Regelaar'
    }
}

const uiText = uiTextLabels[LANGUAGE_CODE] || uiTextLabels.en

function createState(time) {
    return {
        version: 1,
        startedAt: time,
        requestSeq: 0,
        inFlight: null,
        lastCompletedRequestId: 0,
        nextRequestEarliest: 0,
        retry: null,

        // Communication/control state.
        lastCommSuccess: 0,
        commFault: false,
        devmode: null,             // null until confirmed by the device
        requestedDevmode: null,    // pending user UI command, if any
        switchCommandEnabled: false, // armed only after device state is published to UI
        tempBlocked: false,
        controlAdvertisedOff: null,

        // Setpoint state.
        haveSetpoint: false,
        desiredPower: 0,
        setpointGeneration: 0,
        pendingModeConfirmation: null,
        forceSet: false,

        // Scheduling timestamps are attempt times, not success times.
        lastSetAttempt: 0,
        lastDataAttempt: 0,
        lastSetupAttempt: 0,

        // Only the scalar values needed by S2 and the dashboard are cached.
        setupKnown: false,
        targetTemp: null,
        hysteresis: 0,
        minTemp: 20,

        dataValid: false,
        currentTemp: null,
        l1Power: 0,
        l2Power: 0,
        l3Power: 0,
        infoState: 7,

        // Last messages sent to dashboard/virtual-device outputs. Each output is
        // emitted only when its effective value/settings actually change.
        dashboardCache: {},

        // Presence commands must not be sent until the victron-virtual node has
        // actually processed at least one value message. This avoids a startup
        // race in node-red-contrib-victron where setPresence() can run before
        // the virtual node has assigned its D-Bus serviceName.
        temperatureServiceReady: false,
        temperatureProbeFeedbacks: 0,
        temperatureProbeSeq: 0,
        lastTemperatureProbeAt: 0
    }
}

function getState() {
    const stored = flow.get(STATE_KEY)
    if (!stored || stored.version !== 1) {
        const fresh = createState(now)
        flow.set(STATE_KEY, fresh)
        return fresh
    }
    return stored
}

function saveState(state) {
    flow.set(STATE_KEY, state)
}

// Build the Function node's nine dedicated outputs.
// Outputs 1-3 are HTTP requests, 4-8 are dashboard/data outputs,
// and output 9 is reserved exclusively for messages to s2-resource.
// Messages may be accumulated on an output; Node-RED sends them in order.
function newOutputs() {
    return Array.from({ length: 9 }, () => [])
}

function addOutput(outputs, index, message) {
    if (message) outputs[index].push(message)
}

function finishOutputs(outputs) {
    return outputs.map(messages => {
        if (messages.length === 0) return null
        if (messages.length === 1) return messages[0]
        return messages
    })
}

// Dashboard and virtual-device nodes do not need the same value on every
// scheduler tick. Cache the complete outgoing message and emit it only when
// something that the receiving node sees has actually changed.
function addChangedOutput(state, outputs, cacheKey, outputIndex, message) {
    if (!state.dashboardCache || typeof state.dashboardCache !== 'object') {
        state.dashboardCache = {}
    }

    const serialized = JSON.stringify(message)
    if (state.dashboardCache[cacheKey] === serialized) return false

    state.dashboardCache[cacheKey] = serialized
    addOutput(outputs, outputIndex, message)
    return true
}

function updateCommunicationFault(state, time) {
    const reference = state.lastCommSuccess || state.startedAt
    state.commFault = time - reference >= COMMUNICATION_TIMEOUT_MS
}

// OMBC is available only after devmode has actually been learned from the
// device and confirmed as enabled. This prevents startup from accidentally
// assuming devmode=1 and waking a device that was deliberately switched off.
function setTrafficAllowed(state) {
    return (
        state.devmode === 1 &&
        state.requestedDevmode !== 0
    )
}

function isControllable(state) {
    return (
        setTrafficAllowed(state) &&
        !state.tempBlocked &&
        !state.commFault
    )
}

// Output 9 is dedicated to messages sent directly to s2-resource.
function updateAdvertisedControlState(state, outputs) {
    const shouldBeOff = !isControllable(state)

    if (state.controlAdvertisedOff === shouldBeOff) return

    const wasOff = state.controlAdvertisedOff
    state.controlAdvertisedOff = shouldBeOff

    addOutput(outputs, 8, {
        topic: 'ControlTypes',
        payload: { isControllable: !shouldBeOff }
    })

    // When control resumes, send the stored setpoint at the next possible
    // moment. Resetting the attempt timestamp fixes the old stale-timestamp
    // delay that could postpone resumption by several seconds.
    if (wasOff === true && shouldBeOff === false) {
        state.forceSet = true
        state.lastSetAttempt = 0
    }

    // Temperature/communication blocking should push a safe 0 W quickly, but
    // devmode=0 (or unknown) is a hard pause: no SET requests are sent at all.
    if (shouldBeOff && setTrafficAllowed(state)) {
        state.forceSet = true
        state.lastSetAttempt = 0
    }
}

function updateDashboard(state, outputs) {
    const displayDevmode =
        state.requestedDevmode !== null
            ? state.requestedDevmode
            : state.devmode

    // Output 4: Mode switch state and translated UI name. While devmode is
    // unknown, only publish the translated name; publish State once it is known.
    const switchPayload = {
        '/SwitchableOutput/output_1/Settings/CustomName': uiText.mode
    }

    if (displayDevmode === 0 || displayDevmode === 1) {
        switchPayload['/SwitchableOutput/output_1/State'] = displayDevmode
    }

    const switchWasPublished = addChangedOutput(
        state,
        outputs,
        'modeSwitch',
        3,
        { payload: switchPayload }
    )

    // Do not accept the virtual switch's configured startup value as a command.
    // Arm switch commands only after the actual my-PV devmode has been learned
    // and that device-sourced value has been queued to the switch. From then on,
    // subsequent scalar switch output represents user interaction.
    if (
        !state.switchCommandEnabled &&
        switchWasPublished &&
        state.requestedDevmode === null &&
        (state.devmode === 0 || state.devmode === 1)
    ) {
        state.switchCommandEnabled = true
    }

    // Output 7: operation state. Publish this even before telemetry is valid so
    // the dashboard explicitly starts at 7 = Unknown. Failed HTTP requests also
    // set infoState back to 7 in the response handler.
    addChangedOutput(
        state,
        outputs,
        'statusIndicator',
        6,
        {
            payload: {
                '/GenericInput/0/Value': state.infoState,
                '/GenericInput/0/Settings/Labels': labels,
                '/GenericInput/0/Settings/CustomName': uiText.status,
                '/GenericInput/0/Settings/PrimaryLabel': uiText.controller
            }
        }
    )

    // Output 8: Venus OS temperature service. The virtual device is configured
    // with start_disconnected=true, so do not send an explicit connected=false
    // during startup. node-red-contrib-victron 1.7.x can otherwise hit a short
    // initialization race where presenceConnected is true before serviceName has
    // been assigned, causing releaseName(undefined) on D-Bus.
    //
    // Instead, /Temperature probes are sent first (even while the service is
    // offline). The virtual node returns its actual presence state on those
    // passthrough messages. A later probe returning connected=false confirms the
    // start-disconnected initialization has completed; only then may we issue
    // connected=true/false.
    const temperatureServiceConnected =
        !state.commFault &&
        state.currentTemp !== null

    if (state.temperatureServiceReady) {
        addChangedOutput(
            state,
            outputs,
            'temperatureServicePresence',
            7,
            {
                topic: 'TemperatureServicePresence',
                connected: temperatureServiceConnected
            }
        )
    }

    if (!state.dataValid) return

    const sumPower = state.l1Power + state.l2Power + state.l3Power

    // Output 5: water-temperature indicator. Range/label changes also count as
    // a meaningful change because they affect what the user sees.
    addChangedOutput(
        state,
        outputs,
        'waterTemperatureIndicator',
        4,
        {
            payload: {
                '/GenericInput/0/Value': state.currentTemp,
                '/GenericInput/0/Settings/RangeMin': state.minTemp,
                '/GenericInput/0/Settings/RangeMax':
                    state.targetTemp !== null ? state.targetTemp : 90,
                '/GenericInput/0/Settings/CustomName': uiText.waterTemperature
            }
        }
    )

    // Output 6: total reported power.
    addChangedOutput(
        state,
        outputs,
        'powerIndicator',
        5,
        {
            payload: {
                '/GenericInput/0/Value': sumPower,
                '/GenericInput/0/Settings/CustomName': uiText.power,
                '/GenericInput/0/Settings/PrimaryLabel': uiText.reported
            }
        }
    )

    // Before presence control is armed, periodically send an ordinary value
    // message as a harmless readiness probe. The virtual node can process this
    // while its D-Bus name is released. A sequence number makes each probe pass
    // the change filter even when the measured temperature is unchanged.
    if (state.currentTemp !== null && !state.temperatureServiceReady) {
        if (now - state.lastTemperatureProbeAt >= 500) {
            state.temperatureProbeSeq += 1
            state.lastTemperatureProbeAt = now
            addOutput(outputs, 7, {
                topic: 'TemperatureServiceProbe',
                temperatureProbeSeq: state.temperatureProbeSeq,
                payload: {
                    '/Temperature': state.currentTemp
                }
            })
        }
    } else if (state.currentTemp !== null) {
        // Once presence control is known to be safe, normal temperature updates
        // are change-filtered independently from connected=true/false messages.
        addChangedOutput(
            state,
            outputs,
            'temperatureServiceValue',
            7,
            {
                topic: 'TemperatureServiceValue',
                payload: {
                    '/Temperature': state.currentTemp
                }
            }
        )
    }

    const operationState = labels[state.infoState] || labels[7]
    node.status({
        shape: 'dot',
        fill:
            state.devmode === null
                ? 'grey'
                : state.devmode === 0
                  ? 'grey'
                  : state.commFault
                    ? 'red'
                    : state.tempBlocked
                      ? 'yellow'
                      : 'green',
        text:
            `${state.currentTemp ?? '-'} / ` +
            `${state.targetTemp ?? '-'} °C | ` +
            `${sumPower} W | ${operationState}`
    })
}

function temperatureServiceFeedbackReceived(state, message) {
    // victron-virtual adds its actual presence state to ordinary passthrough
    // messages. During startup there is a brief internal sequence of
    // disconnected -> connected -> disconnected when start_disconnected=true.
    // Requiring a later probe (not the first queued one) to come back with
    // connected=false proves that the initial releaseName() has completed and
    // node.serviceName is available before we ever send a presence command.
    if (message.topic === 'TemperatureServiceProbe') {
        const previousFeedbacks = Number(state.temperatureProbeFeedbacks) || 0
        state.temperatureProbeFeedbacks = previousFeedbacks + 1

        if (previousFeedbacks >= 1 && message.connected === false) {
            state.temperatureServiceReady = true
        }

        return true
    }

    if (
        message.topic === 'TemperatureServiceValue' ||
        message.topic === 'TemperatureServicePresence'
    ) {
        return true
    }

    return false
}

function modeInstructionReceived(state, message) {
    // Important: only actual ModeInstruction messages may create a real-device
    // setpoint. ModeRequest and unresolved-mode passthrough messages are ignored.
    if (message.topic !== 'ModeInstruction') return false
    if (!message.payload || message.payload.values === undefined) return false

    const rawValues = message.payload.values
    const phaseValues =
        Array.isArray(rawValues)
            ? rawValues
            : [rawValues]

    const power = phaseValues.reduce(
        (sum, value) => sum + (Number(value) || 0),
        0
    )

    state.haveSetpoint = true
    state.desiredPower = power
    state.setpointGeneration += 1
    state.pendingModeConfirmation = { ...message.payload }
    state.forceSet = true

    return true
}

function devmodeCommandReceived(state, message) {
    // The virtual switch emits a scalar 0/1 (or boolean) on its command output.
    // S2/scheduler messages are excluded so they can never be mistaken for a
    // dashboard devmode command.
    if (
        message.topic === 'SchedulerTick' ||
        message.topic === 'HttpComplete' ||
        message.topic === 'ModeInstruction' ||
        (typeof message.topic === 'string' && message.topic.startsWith('Mode')) ||
        (typeof message.topic === 'string' && message.topic.startsWith('TemperatureService'))
    ) {
        return false
    }

    let requested = null

    if (message.payload === true || message.payload === 1 || message.payload === '1') {
        requested = 1
    } else if (
        message.payload === false ||
        message.payload === 0 ||
        message.payload === '0'
    ) {
        requested = 0
    }

    if (requested === null) return false

    // Critical startup guard: switch_1_initial=0 may produce switch output when
    // the flow is deployed. It is not a user command. Ignore all switch output
    // until we have learned the real my-PV devmode and published it to the UI.
    // This guarantees that requestedDevmode (and therefore ?devmode=...) can be
    // created only by interaction after the initial device-to-UI synchronization.
    if (
        !state.switchCommandEnabled ||
        (state.devmode !== 0 && state.devmode !== 1)
    ) {
        return false
    }

    if (state.devmode === requested) {
        state.requestedDevmode = null
        return true
    }

    state.requestedDevmode = requested

    // Switching off must remove OMBC immediately and pause all SET traffic.
    // Switching on remains non-controllable until the HTTP command succeeds.
    if (requested === 0) {
        state.forceSet = false
    }

    return true
}

function makeRequest(state, type, time, retryDescriptor) {
    state.requestSeq += 1

    const request = {
        requestType: type,
        requestId: state.requestSeq,
        retryAttempt: retryDescriptor?.retryAttempt || 0,
        maxRetries: MAX_RETRIES,
        backoffMs: BACKOFF_MS,
        requestTimeout: HTTP_REQUEST_TIMEOUT_MS
    }

    if (type === 'SetPower') {
        // devmode=0/unknown, or a pending request to switch off, is a hard
        // pause for control.html.
        if (!setTrafficAllowed(state) || !state.haveSetpoint) return null

        const safePower =
            state.tempBlocked || state.commFault
                ? 0
                : state.desiredPower

        request.url =
            `http://${DEVICE_IP}/control.html?power=` +
            encodeURIComponent(safePower)
        request.payload = safePower
        request.power = safePower
        request.setpointGeneration = state.setpointGeneration

        // Only a real ModeInstruction receives a ModeConfirmation. Heartbeats
        // and safety 0 W requests deliberately carry no confirmation payload.
        if (
            safePower === state.desiredPower &&
            state.pendingModeConfirmation
        ) {
            request.modeConfirmationPayload = {
                ...state.pendingModeConfirmation
            }
        }

        state.lastSetAttempt = time
        state.forceSet = false
    } else if (type === 'GetData') {
        request.url = `http://${DEVICE_IP}/data.jsn`

        // Only write devmode when an armed, post-synchronization switch
        // interaction requested an actual change. Normal telemetry requests
        // contain no devmode query parameter at all.
        if (
            state.requestedDevmode !== null &&
            state.requestedDevmode !== state.devmode
        ) {
            request.payload = state.requestedDevmode
            request.requestedDevmode = state.requestedDevmode
            request.url +=
                '?devmode=' +
                encodeURIComponent(state.requestedDevmode)
        }

        state.lastDataAttempt = time
    } else if (type === 'GetSetup') {
        request.url = `http://${DEVICE_IP}/setup.jsn`
        state.lastSetupAttempt = time
    } else {
        return null
    }

    state.inFlight = {
        id: request.requestId,
        type
    }

    state.retry = null
    return request
}

function chooseNextRequest(state, time) {
    if (state.inFlight) return null

    // A failed request gets up to three immediate retries before normal
    // scheduling resumes.
    if (state.retry) {
        // Do not retry an old SET if the device was switched off meanwhile.
        if (
            state.retry.requestType === 'SetPower' &&
            !setTrafficAllowed(state)
        ) {
            state.retry = null
        } else {
            return {
                type: state.retry.requestType,
                retry: state.retry
            }
        }
    }

    // Startup: learn the actual device configuration/devmode before any SET.
    // After three failed retries, pause setup requests briefly instead of
    // hammering the embedded web server. During that pause, read-only data.jsn
    // polling may continue without a devmode query parameter.
    if (
        state.devmode === null &&
        (
            state.lastSetupAttempt === 0 ||
            time - state.lastSetupAttempt >= STARTUP_SETUP_RETRY_INTERVAL_MS
        )
    ) {
        return { type: 'GetSetup', retry: null }
    }

    // A user devmode command is urgent and uses data.jsn as the command endpoint.
    // If all three immediate retries failed, wait until the normal data interval
    // before starting another retry sequence.
    if (
        state.requestedDevmode !== null &&
        state.requestedDevmode !== state.devmode &&
        time - state.lastDataAttempt >= DATA_INTERVAL_MS
    ) {
        return { type: 'GetData', retry: null }
    }

    // A new S2 setpoint or a control-state transition should be applied as soon
    // as possible. SET is still paused completely while devmode != 1.
    if (state.forceSet && state.haveSetpoint && setTrafficAllowed(state)) {
        return { type: 'SetPower', retry: null }
    }

    const candidates = []

    if (time - state.lastDataAttempt >= DATA_INTERVAL_MS) {
        candidates.push({
            type: 'GetData',
            deadline: state.lastDataAttempt + DATA_MAX_INTERVAL_MS
        })
    }

    if (
        state.haveSetpoint &&
        setTrafficAllowed(state) &&
        time - state.lastSetAttempt >= SET_INTERVAL_MS
    ) {
        candidates.push({
            type: 'SetPower',
            deadline: state.lastSetAttempt + SET_MAX_INTERVAL_MS
        })
    }

    // Earliest deadline wins when telemetry and SET become due together.
    // This keeps data.jsn near 2 s and SET near 4 s without concurrent requests.
    if (candidates.length > 0) {
        candidates.sort((a, b) => a.deadline - b.deadline)
        return { type: candidates[0].type, retry: null }
    }

    // setup.jsn is deliberately lowest priority. Missing setup information is
    // retried every few seconds during startup; once known, refresh every 45 s.
    const setupInterval =
        state.setupKnown
            ? SETUP_INTERVAL_MS
            : STARTUP_SETUP_RETRY_INTERVAL_MS

    if (time - state.lastSetupAttempt >= setupInterval) {
        return { type: 'GetSetup', retry: null }
    }

    return null
}

function nextScheduledWake(state, time) {
    if (state.inFlight || state.retry) return null

    const dueTimes = []

    if (state.devmode === null) {
        dueTimes.push(
            state.lastSetupAttempt === 0
                ? time
                : state.lastSetupAttempt + STARTUP_SETUP_RETRY_INTERVAL_MS
        )
    }

    if (
        state.requestedDevmode !== null &&
        state.requestedDevmode !== state.devmode
    ) {
        dueTimes.push(state.lastDataAttempt + DATA_INTERVAL_MS)
    }

    if (state.forceSet && state.haveSetpoint && setTrafficAllowed(state)) {
        dueTimes.push(time)
    }

    dueTimes.push(state.lastDataAttempt + DATA_INTERVAL_MS)

    if (state.haveSetpoint && setTrafficAllowed(state)) {
        dueTimes.push(state.lastSetAttempt + SET_INTERVAL_MS)
    }

    dueTimes.push(
        state.lastSetupAttempt +
        (state.setupKnown
            ? SETUP_INTERVAL_MS
            : STARTUP_SETUP_RETRY_INTERVAL_MS)
    )

    const future = dueTimes
        .filter(value => Number.isFinite(value) && value > time)
        .sort((a, b) => a - b)

    return future.length > 0 ? future[0] : null
}

function dispatchIfPossible(state, outputs, time) {
    if (state.inFlight) return false

    if (time < state.nextRequestEarliest) {
        scheduleWake(state.nextRequestEarliest - time)
        return false
    }

    const next = chooseNextRequest(state, time)

    if (!next) {
        const wakeAt = nextScheduledWake(state, time)
        if (wakeAt !== null) scheduleWake(wakeAt - time)
        return false
    }

    const request = makeRequest(
        state,
        next.type,
        time,
        next.retry
    )

    if (!request) return false

    if (next.type === 'SetPower') {
        // Output 1: SET power HTTP request.
        addOutput(outputs, 0, request)
    } else if (next.type === 'GetData') {
        // Output 2: GET data.jsn HTTP request.
        addOutput(outputs, 1, request)
    } else if (next.type === 'GetSetup') {
        // Output 3: GET setup.jsn HTTP request.
        addOutput(outputs, 2, request)
    }

    return true
}

// Response feedback can arrive only a few milliseconds after an HTTP request.
// A small timer allows the next retry/request to start exactly after BACKOFF_MS
// instead of having to wait for the following 1-second inject tick.
function scheduleWake(delayMs) {
    const delay = Math.max(1, Math.ceil(delayMs))
    const existing = Number(context.get('wakeDue')) || 0
    const due = Date.now() + delay

    if (existing > 0 && existing <= due) return

    context.set('wakeDue', due)

    setTimeout(() => {
        const expectedDue = Number(context.get('wakeDue')) || 0
        if (expectedDue !== due) return
        context.set('wakeDue', 0)

        const wakeNow = Date.now()
        const state = flow.get(STATE_KEY)
        if (!state || state.version !== 1) return

        updateCommunicationFault(state, wakeNow)

        const outputs = newOutputs()
        updateAdvertisedControlState(state, outputs)
        dispatchIfPossible(state, outputs, wakeNow)
        saveState(state)

        const ready = finishOutputs(outputs)
        if (ready.some(Boolean)) node.send(ready)
    }, delay)
}

const state = getState()
const outputs = newOutputs()

// Handle the three possible input sources:
//   1. SchedulerTick from the single 1-second inject node.
//   2. ModeInstruction (and other S2 messages) from s2-resource.
//   3. devmode changes from the dashboard switch.
// HttpComplete feedback from the HTTP-response function simply wakes us up.
temperatureServiceFeedbackReceived(state, msg)
modeInstructionReceived(state, msg)
devmodeCommandReceived(state, msg)

updateCommunicationFault(state, now)
updateAdvertisedControlState(state, outputs)
dispatchIfPossible(state, outputs, now)
updateDashboard(state, outputs)
saveState(state)

return finishOutputs(outputs)

// ============================================================================
// my-PV HTTP response handler
// ============================================================================
// All three HTTP request nodes and their shared Catch node end here.
// This function performs no scheduling. It only:
//   - validates/parses the completed request,
//   - updates the small shared scalar state,
//   - prepares S2 PowerMeasurement / ModeConfirmation messages,
//   - requests up to three retries after failures,
//   - wakes the controller/scheduler.

const STATE_KEY = 'mypv_state'
const now = Date.now()

function numberOrNull(value) {
    if (value === undefined || value === null || value === '') return null
    const number = Number(value)
    return Number.isFinite(number) ? number : null
}

function numberOrZero(value) {
    const number = Number(value)
    return Number.isFinite(number) ? number : 0
}

function parseObject(payload) {
    try {
        const value =
            typeof payload === 'string'
                ? JSON.parse(payload)
                : payload

        return value && typeof value === 'object'
            ? value
            : null
    } catch (error) {
        return null
    }
}

function evaluateTemperatureGate(state) {
    if (
        state.currentTemp === null ||
        state.targetTemp === null
    ) {
        return
    }

    if (state.tempBlocked) {
        if (state.currentTemp < state.targetTemp - state.hysteresis) {
            state.tempBlocked = false
        }
    } else if (state.currentTemp >= state.targetTemp) {
        state.tempBlocked = true
    }
}

function scheduleRetry(state, message, requestType) {
    const attempt = Number(message.retryAttempt) || 0
    const maxRetries = Math.max(0, Number(message.maxRetries) || 3)

    if (attempt >= maxRetries) {
        state.retry = null
        return
    }

    state.retry = {
        requestType,
        retryAttempt: attempt + 1
    }
}

const state = flow.get(STATE_KEY)

if (!state || state.version !== 1) {
    // The scheduler owns state initialization. Wake it so the next tick/request
    // can rebuild state cleanly rather than creating a second state model here.
    return [
        null,
        { topic: 'HttpComplete' }
    ]
}

// Ignore stale or duplicate HTTP completions. Only one request is allowed in
// flight, and every request carries a unique requestId.
if (
    msg.requestId !== undefined &&
    Number(msg.requestId) === Number(state.lastCompletedRequestId)
) {
    return null
}

if (
    state.inFlight &&
    msg.requestId !== undefined &&
    Number(msg.requestId) !== Number(state.inFlight.id)
) {
    return null
}

if (!state.inFlight && msg.requestId !== undefined) {
    return null
}

const requestType =
    msg.requestType ||
    state.inFlight?.type

if (
    requestType !== 'SetPower' &&
    requestType !== 'GetData' &&
    requestType !== 'GetSetup'
) {
    node.warn('Ignoring HTTP response without a valid requestType')
    return null
}

// Mark the serialized request slot free before waking the scheduler.
if (msg.requestId !== undefined) {
    state.lastCompletedRequestId = Number(msg.requestId)
}
state.inFlight = null
state.nextRequestEarliest =
    now + Math.max(0, Number(msg.backoffMs) || 200)

const httpSucceeded =
    !msg.error &&
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300

if (httpSucceeded) {
    state.lastCommSuccess = now
    state.commFault = false
}

let requestSucceeded = httpSucceeded
const s2Messages = []

if (requestType === 'SetPower') {
    if (requestSucceeded) {
        state.retry = null

        // Confirm only real ModeInstructions. Periodic SET heartbeats never
        // carry modeConfirmationPayload.
        if (
            msg.modeConfirmationPayload !== undefined &&
            msg.modeConfirmationPayload !== null
        ) {
            s2Messages.push({
                topic: 'ModeConfirmation',
                payload: msg.modeConfirmationPayload
            })

            // Clear the pending confirmation only if no newer ModeInstruction
            // arrived while this request was in flight.
            if (
                Number(msg.setpointGeneration) ===
                Number(state.setpointGeneration)
            ) {
                state.pendingModeConfirmation = null
            }
        }

        node.status({
            shape: 'dot',
            fill: 'green',
            text: `SET ${Number(msg.power) || 0} W OK`
        })
    }
} else if (requestType === 'GetData') {
    const data = httpSucceeded ? parseObject(msg.payload) : null
    requestSucceeded = httpSucceeded && data !== null

    if (requestSucceeded) {
        state.retry = null
        state.dataValid = true

        const currentTempRaw = numberOrNull(data.temp1)
        state.currentTemp =
            currentTempRaw === null ? null : currentTempRaw / 10

        state.l1Power =
            numberOrZero(data.power1_solar) +
            numberOrZero(data.power1_grid)
        state.l2Power =
            numberOrZero(data.power2_solar) +
            numberOrZero(data.power2_grid)
        state.l3Power =
            numberOrZero(data.power3_solar) +
            numberOrZero(data.power3_grid)

        const rawInfoState = numberOrNull(data.screen_mode_flag)
        state.infoState =
            rawInfoState !== null &&
            rawInfoState >= 0 &&
            rawInfoState <= 6
                ? rawInfoState
                : 7

        // If the request carried a devmode change and the endpoint succeeded,
        // that command is now considered confirmed. If the response itself also
        // contains devmode, it remains authoritative.
        const responseDevmode = numberOrNull(data.devmode)

        if (responseDevmode === 0 || responseDevmode === 1) {
            state.devmode = responseDevmode
        } else if (
            msg.requestedDevmode === 0 ||
            msg.requestedDevmode === 1
        ) {
            state.devmode = Number(msg.requestedDevmode)
        }

        if (
            state.requestedDevmode !== null &&
            state.devmode === state.requestedDevmode
        ) {
            state.requestedDevmode = null
        }

        evaluateTemperatureGate(state)

        s2Messages.push({
            topic: 'PowerMeasurement',
            payload: {
                values: [
                    state.l1Power,
                    state.l2Power,
                    state.l3Power
                ]
            }
        })

        node.status({
            shape: 'dot',
            fill: 'green',
            text: 'data.jsn OK'
        })
    }
} else if (requestType === 'GetSetup') {
    const setup = httpSucceeded ? parseObject(msg.payload) : null
    requestSucceeded = httpSucceeded && setup !== null

    if (requestSucceeded) {
        const devmode = numberOrNull(setup.devmode)

        // On startup, setup.jsn must actually tell us devmode. We deliberately
        // do not default to 1, because that could wake a heater that was off.
        if (
            state.devmode === null &&
            devmode !== 0 &&
            devmode !== 1
        ) {
            requestSucceeded = false
        } else {
            state.retry = null
            state.setupKnown = true

            if (devmode === 0 || devmode === 1) {
                state.devmode = devmode

                if (
                    state.requestedDevmode !== null &&
                    state.devmode === state.requestedDevmode
                ) {
                    state.requestedDevmode = null
                }
            }

            const targetRaw = numberOrNull(setup.ww1target)
            state.targetTemp =
                targetRaw === null ? null : targetRaw / 10

            const hysteresisRaw = numberOrNull(setup.ww_targ_h)
            state.hysteresis =
                hysteresisRaw === null
                    ? 0
                    : Math.max(0, hysteresisRaw / 10)

            const minRaw = numberOrNull(setup.wws_acthor_bsttemp)
            const boostMode = numberOrNull(setup.wws_bstmode)
            state.minTemp =
                boostMode !== null &&
                boostMode !== 0 &&
                minRaw !== null
                    ? minRaw / 10
                    : 20

            evaluateTemperatureGate(state)

            node.status({
                shape: 'dot',
                fill: 'green',
                text: 'setup.jsn OK'
            })
        }
    }
}

if (!requestSucceeded) {
    // The actual operating state is no longer trustworthy after a failed HTTP
    // request or invalid response. Expose 7 = Unknown immediately; the next
    // successful data.jsn response will restore the real state.
    state.infoState = 7

    scheduleRetry(state, msg, requestType)

    const maxRetries = Math.max(0, Number(msg.maxRetries) || 3)

    node.status({
        shape: 'ring',
        fill: 'yellow',
        text:
            `${requestType} failed` +
            (state.retry
                ? `; retry ${state.retry.retryAttempt}/${maxRetries}`
                : '; retries exhausted')
    })
}

flow.set(STATE_KEY, state)

// Output 1: messages that belong back at s2-resource.
// Output 2: wake the central scheduler, which handles backoff, retries,
//           controllability changes, dashboard updates and the next request.
return [
    s2Messages.length > 0 ? s2Messages : null,
    { topic: 'HttpComplete' }
]
